-- İade & Geri Ödeme Politikası tohumu (Google Merchant Center uyumu için herkese açık olmalı)
-- Run: psql -U golden_user -d golden_marketplace -f seed-return-policy.sql
-- İçerik: { lang: { title, body } }. TR + EN tam metin; diğer diller EN'ye düşer.
-- Düzenleme: Admin panel → İçerik Yönetimi → İade Politikası sekmesi.

INSERT INTO "global_settings" ("key", "value", "isPublic", "description", "createdAt", "updatedAt")
VALUES ('return_policy', $POLICYJSON$
{
  "tr": {
    "title": "İade ve Geri Ödeme Politikası",
    "body": "Son güncelleme: Ekim 2026\n\n1. PAZARYERİ MODELİ\nGolden Crafters, satıcı mağazalar ile alıcıları buluşturan bir pazaryeri platformudur (aracı hizmet sağlayıcı). Sitede sergilenen her ürün, ürün sayfasında adı yazan SATICI mağazaya aittir ve satış sözleşmesinin tarafları alıcı ile o satıcıdır. İade talebinin onaylanması, iade kargo süreci, ürün kontrolü ve ücret iadesinin süresi gibi konulardan SATICI sorumludur. Golden Crafters, sürecin bu politikaya uygun yürümesini denetler; satıcıyla çözülemeyen uyuşmazlıklarda alıcı korumasını devreye alır.\n\n2. CAYMA HAKKI (14 GÜN)\nMesafeli satışlarda, ürünü teslim aldığınız günden itibaren 14 gün içinde gerekçe göstermeden cayabilirsiniz. Cayma bildiriminizi sipariş sayfanızdan veya satıcının iletişim kanalından yazılı olarak iletmeniz yeterlidir. Cayma süresi dolmadan bildirilen ürünler için satıcı iadeyi kabul etmek zorundadır.\n\n3. İADE KOŞULLARI\nCayma yoluyla iade edilecek ürünün kullanılmamış, yeniden satılabilir durumda, orijinal ambalajı, sertifikası, faturası ve hediye paketiyle birlikte gönderilmesi gerekir. Altın takılarda ayar damgası, kilit ve taşların eksiksiz olması şarttır. Eksik/hatalı gönderilen ürünlerde iade bedelinden kesinti yapılabilir.\n\n4. İADE EDİLEMEYEN ÜRÜNLER\nAşağıdaki ürünlerde sağlık ve hijyen gerekçesiyle cayma hakkı kullanılamaz:\n- Ambalajı açılmış küpe, piercing, hızma, burun halkası ve vücuda temas eden tüm takılar,\n- Kişiye özel üretilen ürünler (isimli alyans, ölçüye göre imal edilen tasarımlar),\n- Niteliği gereği iade edilemeyecek, çabuk bozulabilen veya ambalajı açıldığında iadesi sağlık açısından sakıncalı ürünler.\nAmbalajı hiç açılmamış hijyenik ürünlerde 14 günlük cayma hakkı geçerlidir.\n\n5. AYIPLI ÜRÜN\nKırık kilit, düşen taş, kararma/renk atması gibi üretim veya malzeme kusurlarında 6502 sayılı kanundaki ayıplı mal haklarınız saklıdır: ücretsiz onarım, ayıpsız misliyle değişim veya bedel iadesi seçeneklerinden birini isteyebilirsiniz. Ayıplı üründe iade kargo ücreti SATICIYA aittir ve satıcı, kusur iddianızı makul sürede incelemek zorundadır.\n\n6. İADE ADIMLARI\n1) Sipariş sayfanızdan iade talebi açın ve nedenini seçin.\n2) Satıcı talebi en geç 3 iş günü içinde yanıtlar ve iade adresini iletir.\n3) Ürünü, onaydan itibaren 10 gün içinde anlaşmalı/tercih ettiğiniz kargoyla gönderin.\n4) Satıcı ürünü teslim alıp en geç 3 iş günü içinde kontrol eder.\n5) Onaylanan iadenin bedeli, iade onayından itibaren 14 gün içinde ödeme yaptığınız yönteme iade edilir.\n\n7. KARGO VE MASRAFLAR\nCayma hakkıyla iadede gidiş kargo ücreti alıcıya aittir. Satıcının kusurundan kaynaklanan iadelerde (ayıplı/yanlış/eksik ürün) tüm kargo masraflarını satıcı karşılar. Kapıda ödemeli iade gönderilerinde doğan ek ücretler iade bedelinden düşülebilir.\n\n8. ÜCRET İADESİ\nİade bedeli, ödemeyi yaptığınız karta/hesaba yatırılır. Kredi kartına taksitli alışverişlerde bankanızın iade işlem süresi (genellikle 2-14 gün) ayrıca uygulanır ve bu süre bankanıza bağlıdır. Havale/EFT ile ödemelerde iade, bildirdiğiniz IBAN'a yapılır.\n\n9. UYUŞMAZLIK ÇÖZÜMÜ\nÖnce satıcıyla, çözülmezse platform destek ekibiyle iletişime geçin. Çözülemeyen uyuşmazlıklarda parasal sınırlar dahilinde Tüketici Hakem Heyetlerine, üzerindeki tutarlarda Tüketici Mahkemelerine başvurabilirsiniz.\n\n10. İLETİŞİM\nİade talepleriniz ve sorularınız için önce ilgili satıcının mağaza sayfasındaki iletişim kanallarını, ardından platform destek hattını kullanın."
  },
  "en": {
    "title": "Return and Refund Policy",
    "body": "Last updated: October 2026\n\n1. MARKETPLACE MODEL\nGolden Crafters is a marketplace platform (intermediary service provider) connecting seller stores with buyers. Each product belongs to the SELLER store named on the product page, and the sales contract is between the buyer and that seller. The SELLER is responsible for approving return requests, the return shipping process, product inspection and refund timelines. Golden Crafters supervises compliance with this policy and activates buyer protection for disputes that cannot be resolved with the seller.\n\n2. RIGHT OF WITHDRAWAL (14 DAYS)\nFor distance sales, you may withdraw without giving any reason within 14 days from the day you receive the product. A written notice via your orders page or the seller's contact channel is sufficient. Sellers must accept returns notified within the withdrawal period.\n\n3. RETURN CONDITIONS\nProducts returned under withdrawal must be unused, resalable, and shipped with original packaging, certificates, invoice and gift wrapping. For gold jewelry, hallmarks, clasps and stones must be intact. Missing items may be deducted from the refund.\n\n4. NON-RETURNABLE PRODUCTS\nFor health and hygiene reasons, the right of withdrawal cannot be used for:\n- Opened earrings, piercings, nose studs/rings and all body-contact jewelry,\n- Custom-made products (engraved bands, made-to-measure designs),\n- Products that by nature cannot be returned or whose return poses a health risk once unsealed.\nThe 14-day withdrawal right applies to hygienic products whose packaging was never opened.\n\n5. DEFECTIVE PRODUCTS\nFor manufacturing or material defects (broken clasps, fallen stones, discoloration), your statutory rights for defective goods are reserved: free repair, replacement, or refund. Return shipping for defective products is paid by the SELLER, who must inspect your claim within a reasonable time.\n\n6. RETURN STEPS\n1) Open a return request from your orders page and select a reason.\n2) The seller responds within 3 business days with the return address.\n3) Ship the product within 10 days of approval.\n4) The seller inspects the product within 3 business days of receipt.\n5) Approved refunds are returned to your original payment method within 14 days of approval.\n\n7. SHIPPING COSTS\nFor withdrawal returns, outbound shipping is paid by the buyer. For seller-fault returns (defective/wrong/incomplete products), the seller covers all shipping costs. Extra fees from cash-on-delivery return shipments may be deducted from the refund.\n\n8. REFUNDS\nRefunds go back to your card/account. For installment card purchases, your bank's processing time (usually 2-14 days) additionally applies. Bank/wire payments are refunded to the IBAN you provide.\n\n9. DISPUTE RESOLUTION\nContact the seller first, then platform support. Unresolved disputes may be taken to the relevant consumer arbitration or courts.\n\n10. CONTACT\nFor return requests and questions, use the seller's contact channels on their store page first, then platform support."
  }
}
$POLICYJSON$, true, 'Public return & refund policy (multi-language JSON)', NOW(), NOW())
ON CONFLICT ("key") DO UPDATE SET "value" = EXCLUDED."value", "isPublic" = true, "updatedAt" = NOW();
